function whereToFind(x){
const q=encodeURIComponent(x.title),musicQ=encodeURIComponent(x.title+' '+(x.creator||''));
const platforms=x.type==='Book'?[['Open Library','https://openlibrary.org/search?q='+q,'▤'],['Google Books','https://www.google.com/search?tbm=bks&q='+q,'▤']]:x.type==='Music'?[['Spotify','https://open.spotify.com/search/'+musicQ,'♫']]:x.type==='Visual novel'?[['VNDB','https://vndb.org/v?sq='+q,'VN'],['Steam','https://store.steampowered.com/search/?term='+q,'steam']]:x.type==='Game'?[['Steam','https://store.steampowered.com/search/?term='+q,'steam'],['itch.io','https://itch.io/search?q='+q,'▧']]:[['JustWatch (US)','https://www.justwatch.com/us/search?q='+q,'▷'],['YouTube','https://www.youtube.com/results?search_query='+encodeURIComponent(x.title+' official trailer'),'▶']];
const custom=safeMediaUrl(x.mediaUrl||'');
return `<section class="where-section" aria-label="Where to find it"><h3>Where to find it</h3><p class="disclaimer">Search these services for this title. Availability, editions, and region access haven’t been verified.</p><div class="platform-links">${platforms.map(([label,url,icon])=>`<a class="platform-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer"><span class="platform-icon" aria-hidden="true">${icon==='steam'?'<img src="assets/steam.svg" alt="" width="22" height="22">':icon}</span><span><b>${esc(label)}</b><small>Search title</small></span><span class="external-arrow" aria-hidden="true">↗</span></a>`).join('')}${custom?`<a class="platform-link custom-platform" href="${esc(custom)}" target="_blank" rel="noopener noreferrer"><span class="platform-icon" aria-hidden="true">↗</span><span><b>${esc(x.mediaLinkLabel||'My saved link')}</b><small>Your saved link</small></span><span class="external-arrow" aria-hidden="true">↗</span></a>`:''}</div></section>`;
}
function descriptionSection(x){
const placeholder=!x.description||['Explore this title and make it part of your collection.','A personal addition to your library.'].includes(x.description);
const description=placeholder?(catalogBase.find(entry=>entry.id===x.id)?.description||'No description yet. A brief overview of this title will appear here when metadata is added.'):x.description;
return `<section class="description-section" aria-label="Description"><div class="description-heading"><h3>Description</h3><span>${placeholder&&!catalogBase.some(entry=>entry.id===x.id)?'COMING SOON':'PROTOTYPE SUMMARY'}</span></div><p class="description">${esc(description)}</p></section>`;
}
function detailHeader(x){
const variant=[...x.title].reduce((sum,c)=>sum+c.charCodeAt(0),0)%3;
const scenes={
landscape:`<circle cx="690" cy="105" r="62" fill="currentColor" opacity=".48"/><path d="M0 300 Q170 130 350 270 T900 240 V400 H0Z" fill="#101b21" opacity=".65"/><path d="M0 330 Q230 200 480 310 T900 245 V400 H0Z" fill="#152019"/><path d="M0 350 Q250 280 460 340 T900 310 V400 H0Z" fill="#1b2219"/>`,
city:`<circle cx="695" cy="110" r="70" fill="currentColor" opacity=".27"/><path d="M0 310H390V235H435V270H470V175H515V240H550V125H590V250H620V205H670V155H710V230H760V190H810V260H900V400H0Z" fill="#101c21" opacity=".8"/><path d="M570 150V240M490 200V265M690 180V260M790 215V290" stroke="currentColor" stroke-width="3" opacity=".3"/>`,
music:`<g fill="none" stroke="currentColor"><circle cx="670" cy="175" r="125" stroke-width="1" opacity=".22"/><circle cx="670" cy="175" r="100" stroke-width="18" opacity=".08"/><circle cx="670" cy="175" r="68" stroke-width="1" opacity=".38"/><circle cx="670" cy="175" r="26" stroke-width="3" opacity=".4"/><path d="M0 220 Q170 40 350 200 T900 170 M0 245 Q170 65 350 225 T900 195 M0 270 Q170 90 350 250 T900 220" opacity=".15"/></g>`};
const scene=x.type==='Music'?scenes.music:variant===1?scenes.city:scenes.landscape;
return `<div class="detail-header" style="--detail-art:${esc(x.color||colors[0])}"><div class="detail-art" aria-hidden="true">${safeMediaUrl(x.backgroundUrl||'')?`<img class="custom-background" src="${esc(x.backgroundUrl)}" alt="">`:''}${safeArt(x.backgroundImage)?`<img class="custom-background" src="${esc(safeArt(x.backgroundImage))}" alt="">`:''}<svg viewBox="0 0 900 400" preserveAspectRatio="xMidYMid slice" focusable="false">${scene}</svg></div><div class="detail-top">${cover(x)}<div class="detail-title"><small>${esc(x.type.toUpperCase())} · ${esc(x.year||'YEAR UNKNOWN')}</small><h2>${esc(x.title)}</h2><p class="muted">${esc(x.creator||'Creator not added')}<br>${esc(x.genre||'Your collection')}</p></div></div></div>`;
}
function openDetail(id){const x=catalogItems().find(x=>x.id===id);if(!x)return;const entry=owned(x);if(entry){openOwnedDetail(entry.id);return}
$('#detail-content').innerHTML=`${detailHeader(x)}${descriptionSection(x)}${x.sources.length?`<div class="source-heading"><h3>Community ratings</h3><span>DEMO DATA</span></div><div class="ratings">${ratingCards(x.sources)}</div>`:''}${whereToFind(x)}<p class="disclaimer">Sample catalog entry. Live metadata and reviews are not connected.</p><button class="primary" id="detail-add">＋ Add to library</button>`;
$('#detail-add').onclick=()=>openCatalogAdd(id);if(!$('#detail').open)$('#detail').showModal();$('#detail-content').scrollTop=0;
}
function navigateMedia(hash){if($('#detail').open)$('#detail').close();history.pushState(null,'',hash);routeMedia();window.scrollTo({top:0,behavior:'instant'})}
function localDateTime(){const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function readableDate(value){if(!value)return 'Date not recorded';const d=new Date(value);return Number.isNaN(d.getTime())?'Date not recorded':d.toLocaleString([], {year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}
function activitySection(x){const p=x.episodeProgress||{},sessions=x.sessions||[];return `<section class="activity-section"><div class="section-heading"><h3>Progress & activity</h3><button class="secondary" id="log-session">＋ Log session</button></div><form id="episode-form" class="episode-form"><label>Progress unit<select id="progress-unit">${[...new Set([x.progressUnit||defaultUnit(x),'Episodes','Hours','Chapters','Pages','Tracks','Percent'])].map(u=>`<option>${esc(u)}</option>`).join('')}</select></label><div class="row"><label>Progress completed<input id="episodes-done" type="number" min="0" step="any" required value="${esc(p.completed||0)}"></label><label>Total (optional)<input id="episodes-total" type="number" min="1" step="any" value="${esc(p.total||'')}" placeholder="Unknown"></label><button class="secondary" type="submit">Save progress</button></div><p class="disclaimer">Use episode tracking for series or any episodic media. Progress won’t automatically mark the title completed.</p><p id="episode-error" class="link-error" role="alert" hidden></p></form>${p.total?`<progress value="${p.completed||0}" max="${p.total}" aria-label="Episode progress"></progress><p class="muted">${p.completed||0} of ${p.total} completed</p>`:''}<div class="session-list">${sessions.slice().sort((a,b)=>b.started.localeCompare(a.started)).map(entry=>`<details class="journal-entry"><summary><span>${esc(entry.label||'Consumption session')}</span><time>${esc(readableDate(entry.started))}</time></summary><div class="entry-body"><p>Started: ${esc(readableDate(entry.started))}${entry.ended?'<br>Finished: '+esc(readableDate(entry.ended))+' · '+((new Date(entry.ended)-new Date(entry.started))/3600000).toFixed(2)+' hours':''}</p>${entry.episodeTo?`<p>Episodes ${entry.episodeFrom||entry.episodeTo}–${entry.episodeTo}</p>`:''}${entry.note?`<p class="preserve-lines">${esc(entry.note)}</p>`:''}<button class="text-button" data-session-edit="${esc(entry.id)}">Edit session</button></div></details>`).join('')||'<p class="muted">No sessions logged. Record when you watched, read, played, or listened.</p>'}</div></section>`}
function journalSection(x){const notes=x.journal||[];return `<section class="journal-section"><div class="section-heading"><h3>Notes journal <small>${notes.length}</small></h3><button class="secondary" id="new-journal-note">＋ Add note</button></div>${x.notes?`<details class="journal-entry"><summary><span>Quick summary</span><time>Undated</time></summary><div class="entry-body preserve-lines">${esc(x.notes)}</div></details>`:''}${notes.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(note=>`<details class="journal-entry"><summary><span>${esc(note.title)}</span><time>${esc(readableDate(note.date))}</time></summary><div class="entry-body"><div class="rich-note">${noteMarkup(note)}</div><button class="text-button" data-note-edit="${esc(note.id)}">Edit note</button></div></details>`).join('')||'<p class="muted">Keep separate notes for each chapter, episode, or thought. Click a dated title to read it.</p>'}</section>`}
function bindActivity(x){$('#log-session').onclick=()=>openSessionEditor(x.id);$('#new-journal-note').onclick=()=>openJournalEditor(x.id);$('#episode-form').onsubmit=e=>{e.preventDefault();const completed=Number($('#episodes-done').value),total=$('#episodes-total').value?Number($('#episodes-total').value):null;if(!Number.isFinite(completed)||completed<0||(total!==null&&(!Number.isFinite(total)||total<1||completed>total))){$('#episode-error').textContent='Enter whole numbers; completed episodes cannot exceed the total.';$('#episode-error').hidden=false;return}x.progressUnit=$('#progress-unit').value;x.episodeProgress={completed,total};if(persist())toast('Progress saved');const scroll=$('#detail-content').scrollTop;openOwnedDetail(x.id);$('#detail-content').scrollTop=scroll};document.querySelectorAll('[data-session-edit]').forEach(b=>b.onclick=()=>openSessionEditor(x.id,b.dataset.sessionEdit));document.querySelectorAll('[data-note-edit]').forEach(b=>b.onclick=()=>openJournalEditor(x.id,b.dataset.noteEdit))}
function showEntryEditor(x,title,body){$('#detail-content').innerHTML=`<div class="entry-editor"><button class="back-link" id="entry-back">← Back to status</button><small>${esc(x.title)}</small><h2>${esc(title)}</h2>${body}</div>`;$('#entry-back').onclick=()=>openOwnedDetail(x.id);$('#entry-cancel').onclick=()=>openOwnedDetail(x.id);$('#detail-content').scrollTop=0}
function openJournalEditor(id,noteId=null){const x=items.find(x=>x.id===id);if(!x)return;const note=(x.journal||[]).find(n=>n.id===noteId);showEntryEditor(x,note?'Edit note':'New journal note',`<form id="journal-form"><label>Title<input id="note-title" required maxlength="120" value="${esc(note?.title||'')}" placeholder="e.g. First impressions"></label><label>Date and time<input id="note-date" type="datetime-local" required value="${esc(note?.date||localDateTime())}"></label><div class="note-toolbar" role="toolbar" aria-label="Note formatting"><button type="button" data-format="bold" aria-label="Bold"><b>B</b></button><button type="button" data-format="italic" aria-label="Italic"><i>I</i></button><button type="button" data-format="underline" aria-label="Underline"><u>U</u></button><button type="button" data-block="h2">Heading 1</button><button type="button" data-block="h3">Heading 2</button><button type="button" data-block="p">Paragraph</button><button type="button" data-format="insertUnorderedList" aria-label="Bullet list">• List</button><button type="button" data-format="insertOrderedList" aria-label="Numbered list">1. List</button></div><div id="note-body" class="rich-editor" contenteditable="true" role="textbox" aria-label="Note text" aria-multiline="true">${note?noteMarkup(note):'<p><br></p>'}</div><div class="actions"><button class="secondary" id="entry-cancel" type="button">Cancel</button><button class="primary" type="submit">Save note</button></div>${note?'<button class="remove" id="delete-note" type="button">Delete note</button>':''}</form>`);
const editor=$('#note-body');document.querySelectorAll('.note-toolbar button').forEach(button=>{button.onmousedown=e=>e.preventDefault();button.onclick=()=>{editor.focus();document.execCommand(button.dataset.block?'formatBlock':button.dataset.format,false,button.dataset.block||null)}});editor.onpaste=e=>{e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'))};
$('#journal-form').onsubmit=e=>{e.preventDefault();const title=$('#note-title').value.trim(),body=editor.innerText.trim(),bodyHTML=sanitizeNote(editor.innerHTML);if(!title||!body){toast('Add a title and note text');return}if(body.length>20000){toast('Keep each note under 20,000 characters');return}const entry={id:noteId||crypto.randomUUID(),title,body,bodyHTML,date:$('#note-date').value};const before=x.journal;x.journal=(x.journal||[]).filter(n=>n.id!==entry.id).concat(entry);if(!persist()){x.journal=before;return}toast('Note saved');openOwnedDetail(id)};if(note)$('#delete-note').onclick=()=>{if(confirm('Delete this note?')){x.journal=x.journal.filter(n=>n.id!==noteId);persist();openOwnedDetail(id)}}}
function openSessionEditor(id,sessionId=null){const x=items.find(x=>x.id===id);if(!x)return;const entry=(x.sessions||[]).find(n=>n.id===sessionId);showEntryEditor(x,entry?'Edit session':'Log a session',`<form id="session-form"><div class="row"><label>Started<input id="session-start" type="datetime-local" required value="${esc(entry?.started||localDateTime())}"></label><label>Finished (optional)<input id="session-end" type="datetime-local" value="${esc(entry?.ended||'')}"></label></div><div class="row"><label>From episode (optional)<input id="session-from" type="number" min="1" step="1" value="${esc(entry?.episodeFrom||'')}"></label><label>Through episode (optional)<input id="session-to" type="number" min="1" step="1" value="${esc(entry?.episodeTo||'')}"></label></div><p class="disclaimer">Sessions are a history log. Set your overall episode progress separately.</p><label>Session note<textarea id="session-note" maxlength="3000" rows="4">${esc(entry?.note||'')}</textarea></label><p id="session-error" class="link-error" role="alert" hidden></p><div class="actions"><button class="secondary" id="entry-cancel" type="button">Cancel</button><button class="primary" type="submit">Save session</button></div>${entry?'<button class="remove" id="delete-session" type="button">Delete session</button>':''}</form>`);$('#session-form').onsubmit=e=>{e.preventDefault();const started=$('#session-start').value,ended=$('#session-end').value,from=Number($('#session-from').value)||null,to=Number($('#session-to').value)||null,label='Session';if(!label||(ended&&ended<started)||((from||to)&&(!from||!to||from>to||!Number.isInteger(from)||!Number.isInteger(to)))){$('#session-error').textContent='Add a title, keep the finish after the start, and enter both episode bounds in order (or leave both empty).';$('#session-error').hidden=false;return}const next={id:sessionId||crypto.randomUUID(),label,started,ended,episodeFrom:from,episodeTo:to,note:$('#session-note').value.trim()};x.sessions=(x.sessions||[]).filter(n=>n.id!==next.id).concat(next);if(persist())toast('Session saved');openOwnedDetail(id)};if(entry)$('#delete-session').onclick=()=>{if(confirm('Delete this session?')){x.sessions=x.sessions.filter(n=>n.id!==sessionId);persist();openOwnedDetail(id)}}}

let libraryScroll=0;
function openOwnedDetail(id){
const x=items.find(item=>item.id===id);if(!x)return;currentId=id;
const returning=$('#library-page').hidden;
if(!returning)libraryScroll=window.scrollY;
if(location.hash.startsWith('#media/'))history.replaceState(null,'','#library');
$('#library-page').hidden=view==='home';$('#media-page').hidden=true;$('#media-page').innerHTML='';if(returning)render();
$('#detail-content').innerHTML=`${detailHeader(x)}<div class="popup-summary"><div class="personal-summary"><span>${esc(x.status==='Want to experience'?'Up next':x.status)}</span><span>${x.rating?'★ '+x.rating+' / 10':'Not rated'}</span>${x.favorite?'<span>♥ Favorite</span>':''}</div><button class="secondary" id="edit-media" aria-label="Edit ${esc(x.title)}">⚙ Edit properties</button></div>${descriptionSection(x)}<div class="source-heading"><h3>Community ratings</h3><span>${x.sources.length?(x.metadata?'PROVIDER RATINGS':'DEMO DATA'):'NO SOURCES'}</span></div><div class="ratings">${ratingCards(x.sources)||'<p class="muted">No external ratings yet.</p>'}</div><p class="disclaimer">${x.metadata?'Ratings retain their provider and original scale.':'Illustrative scores from the sample collection.'}</p>${whereToFind(x)}${activitySection(x)}${journalSection(x)}`;
$('#edit-media').onclick=()=>openMediaEditor(x.id);bindActivity(x);
if(returning)window.scrollTo({top:libraryScroll,behavior:'instant'});
if(!$('#detail').open)$('#detail').showModal();$('#detail-content').scrollTop=0;
}

function openMediaEditor(id){const x=items.find(item=>item.id===id);if(!x)return;currentId=id;
$('#library-page').hidden=false;$('#media-page').hidden=true;
$('#detail-content').innerHTML=`<div class="page-nav"><button class="back-link" id="back-media">← Back to ${esc(x.title)}</button></div><div class="edit-heading"><small>YOUR LIBRARY</small><h1>Edit media<span>.</span></h1><p>${esc(x.title)}</p></div><div class="edit-panel"><div class="detail-fields edit-fields">${customProperties(x)}<div class="row"><label>Your status<select id="edit-status">${statuses.map(s=>`<option ${s===x.status?'selected':''}>${s}</option>`).join('')}</select></label><label>Your rating<select id="edit-rating"><option value="0">Not rated</option>${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${x.rating===i+1?'selected':''}>${i+1} / 10</option>`).join('')}</select></label></div><fieldset class="saved-link-fields"><legend>Your own media link</legend><p class="disclaimer">Save a direct store, streaming, or website link. Clear the URL to remove it.</p><div class="row"><label>Link name<input id="edit-link-label" maxlength="60" placeholder="e.g. My Spotify album" value="${esc(x.mediaLinkLabel||'')}"></label><label>Link URL<input id="edit-link-url" type="url" placeholder="https://…" value="${esc(x.mediaUrl||'')}" aria-describedby="link-error"></label></div><p id="link-error" class="link-error" role="alert" hidden></p></fieldset><fieldset class="saved-link-fields"><legend>Collections</legend><div id="edit-collections">${collections.map(c=>`<label class="collection-member"><input type="checkbox" value="${esc(c.id)}" ${c.members.includes(x.id)?'checked':''}><span>${esc(c.name)}</span></label>`).join('')||'<p class="muted">Create a collection from your library to organize this title.</p>'}</div></fieldset><label>Cover image URL<input id="cover-url" type="url" value="${esc(x.coverUrl||'')}" placeholder="https://…"></label><label>Background image URL<input id="background-url" type="url" value="${esc(x.backgroundUrl||'')}" placeholder="https://…"></label><label>Genre<input id="edit-genre" value="${esc(x.genre||'')}"></label><label>Quick summary<textarea id="edit-notes" maxlength="3000" rows="3" placeholder="What stayed with you?">${esc(x.notes)}</textarea></label><div class="actions"><button id="cancel-edit" class="secondary">Cancel</button><button id="favorite" class="secondary">${x.favorite?'♥ Favorited':'♡ Add to favorites'}</button><button id="save" class="primary">Save changes</button></div><p><button id="remove" class="remove">Remove from library</button></p></div></div>`;
let draftFavorite=!!x.favorite;const artDraft=bindCustomProperties(x);
$('#back-media').onclick=$('#cancel-edit').onclick=()=>openOwnedDetail(x.id);
$('#edit-rating').value=x.rating||0;
$('#favorite').onclick=()=>{draftFavorite=!draftFavorite;$('#favorite').textContent=draftFavorite?'♥ Favorited':'♡ Add to favorites'};
$('#save').onclick=()=>{const raw=$('#edit-link-url').value.trim(),url=raw?safeMediaUrl(raw):'';if(raw&&!url){$('#link-error').textContent='Enter a complete http:// or https:// link.';$('#link-error').hidden=false;$('#edit-link-url').focus();return}const snapshot=JSON.parse(JSON.stringify(x));const collectionSnapshot=collections.map(c=>({...c,members:[...c.members]}));x.type=$('#edit-type').value;x.genre=$('#edit-genre').value.trim();x.coverImage=artDraft.coverImage;x.backgroundImage=artDraft.backgroundImage;x.coverUrl=safeMediaUrl($('#cover-url').value);x.backgroundUrl=safeMediaUrl($('#background-url').value);x.genre=$('#edit-genre').value.trim();x.mediaUrl=url;x.mediaLinkLabel=$('#edit-link-label').value.trim();x.status=$('#edit-status').value;x.rating=Number($('#edit-rating').value);x.notes=$('#edit-notes').value;x.favorite=draftFavorite;const memberships=new Set([...document.querySelectorAll('#edit-collections input:checked')].map(input=>input.value));collections=collections.map(c=>({...c,members:memberships.has(c.id)?[...new Set([...c.members,x.id])]:c.members.filter(id=>id!==x.id)}));if(!persist()){Object.assign(x,snapshot);collections=collectionSnapshot;return}saveCollections();toast('Changes saved');const scroll=window.scrollY;render();window.scrollTo({top:scroll,behavior:'instant'});openOwnedDetail(x.id)};
$('#remove').onclick=()=>{if(confirm('Remove '+x.title+' from your library?')){items=items.filter(y=>y.id!==x.id);persist();navigateMedia('#library');toast('Removed from library')}};
if(!$('#detail').open)$('#detail').showModal();$('#detail-content').scrollTop=0;
}
function routeMedia(){const match=location.hash.match(/^#media\/([^/]+)(\/edit)?$/);const x=match?items.find(item=>item.id===decodeURIComponent(match[1])):null;if(x){history.replaceState(null,'','#library');match[2]?openMediaEditor(x.id):openOwnedDetail(x.id);return}if($('#detail').open)$('#detail').close();view=location.hash==='#home'||!location.hash?'home':location.hash==='#search'?'catalog':'all';$('#library-page').hidden=false;$('#media-page').hidden=true;render()}
window.addEventListener('popstate',routeMedia);window.addEventListener('hashchange',routeMedia);
$('#nav').onclick=e=>{const b=e.target.closest('[data-view]');if(b){history.pushState(null,'',b.dataset.view==='home'?'#home':b.dataset.view==='catalog'?'#search':'#library');selection.clear();selectMode=false;$('#library-page').hidden=false;$('#media-page').hidden=true;view=b.dataset.view;type='All media';$('#search').value='';$('#status').value='all';$('#sort').value='recent';$('#availability').value='all';$('#genre-filter').value='all';render()}};
$('#tabs').onclick=e=>{const b=e.target.closest('[data-type]');if(b){type=b.dataset.type;render()}};
let menuTrigger=null;
function closeItemMenu(){const menu=$('#item-menu');if(menu)menu.hidden=true;if(menuTrigger){menuTrigger.setAttribute('aria-expanded','false');menuTrigger=null}}
function openItemMenu(id,left,top,trigger){closeItemMenu();const x=items.find(x=>x.id===id);if(!x)return;const menu=$('#item-menu');const entries=[['view','View media'],['favorite',x.favorite?'Remove favorite':'Add to favorites'],['progress','Set progress…'],...statuses.map((s,i)=>['status-'+i,(x.status===s?'✓ ':'')+(s==='Want to experience'?'Up next':s)]),['edit','Edit properties'],['remove','Remove from library']];menu.innerHTML=`<div class="menu-title">${esc(x.title)}</div>`+entries.map(([key,label],i)=>`${i===2?'<div class="menu-section">Progress & status</div>':i===7?'<div class="menu-section">Manage title</div>':''}<button class="${key==='remove'?'danger':''}" role="menuitem" data-menu-action="${key}">${label}</button>`).join('');menu.hidden=false;menu.style.left=Math.max(8,Math.min(left,window.innerWidth-222))+'px';menu.style.top=Math.max(8,Math.min(top,window.innerHeight-menu.offsetHeight-8))+'px';menuTrigger=trigger;trigger?.setAttribute('aria-expanded','true');menu.onclick=e=>{const button=e.target.closest('[data-menu-action]');if(!button)return;const action=button.dataset.menuAction;closeItemMenu();if(action==='view')return openOwnedDetail(id);if(action==='edit')return openMediaEditor(id);if(action==='progress'){openOwnedDetail(id);$('#episode-form').scrollIntoView({block:'center'});$('#episodes-done').focus();return}if(action==='favorite')x.favorite=!x.favorite;if(action.startsWith('status-'))x.status=statuses[Number(action.split('-')[1])];if(action==='remove'){if(!confirm('Remove '+x.title+' from your library?'))return;items=items.filter(item=>item.id!==id)}persist();render()};menu.querySelector('button').focus()}
$('#grid').oncontextmenu=e=>{const card=e.target.closest('[data-library-id]');if(card){e.preventDefault();openItemMenu(card.dataset.libraryId,e.clientX,e.clientY,card.querySelector('[data-options]'))}};
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#item-menu')&&!e.target.closest('[data-options]'))closeItemMenu()});
