let detailBackdropPress=false;
function outsideDetail(event){const rect=$('#detail').getBoundingClientRect();return event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom}
$('#detail').addEventListener('pointerdown',event=>{detailBackdropPress=event.target===$('#detail')&&outsideDetail(event)});
