$('#add-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim();if(!title){toast('Enter a title');return}const x={id:crypto.randomUUID(),title,type:f.get('type'),year:f.get('year'),creator:f.get('creator').trim(),genre:f.get('genre').trim(),status:f.get('status'),notes:f.get('notes'),rating:0,favorite:false,added:Date.now(),color:colors[Math.max(0,types.indexOf(f.get('type'))-1)%colors.length],symbol:'✦',sources:[],description:''};items.unshift(x);persist();view='all';type='All media';$('#search').value='';$('#status').value='all';$('#sort').value='recent';render();e.target.reset();$('#add-dialog').close();toast('Added to your library');openDetail(x.id)};
