$('#type-form').onsubmit=e=>{e.preventDefault();const name=$('#type-name').value.trim();if(!name||types.some(t=>t.toLowerCase()===name.toLowerCase())){$('#type-error').textContent='Choose a unique media type name.';$('#type-error').hidden=false;return}removedTypes=removedTypes.filter(t=>t!==name);localStorage.setItem('folio-removed-types',JSON.stringify(removedTypes));customTypes.push(name);types.push(name);labels.push(name);localStorage.setItem('folio-types-v1',JSON.stringify(customTypes));syncCustomTypes();render();renderSettings();$('#type-dialog').close();toast('Media type created')};

