function updateCollectionPreview(){const image=safeArt($('#collection-cover').value||collectionPicture);$('#collection-preview').hidden=!image;$('#collection-preview').src=image||''}
$('#collection-cover').oninput=updateCollectionPreview;
$('#collection-upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2000000){toast('Choose a PNG, JPEG, or WebP smaller than 2 MB');return}const reader=new FileReader();reader.onload=()=>{collectionPicture=reader.result;$('#collection-cover').value='';updateCollectionPreview()};reader.readAsDataURL(file)};
$('#space-media').onclick=()=>{collectionSpace=false;selectedCollection='all';render()};
$('#space-collections').onclick=$('#collection-back').onclick=()=>{collectionSpace=true;selectedCollection='all';$('#search').value='';render()};
function renderLibrary(){renderMedia();const browsing=view==='catalog';$('#library-spaces').hidden=browsing;$('#space-media').classList.toggle('selected',!collectionSpace&&selectedCollection==='all');$('#space-collections').classList.toggle('selected',collectionSpace||selectedCollection!=='all');$('#collection-back').hidden=selectedCollection==='all'||browsing;$('#collection-bar>div').hidden=true;$('#collection-bar').hidden=browsing;$('#new-collection').hidden=browsing||!collectionSpace;$('#manage-collection').hidden=selectedCollection==='all'||browsing;for(const selector of ['#tabs','.facet-filters','#layout-controls','#status','#sort','.favorites-filter'])$(selector).hidden=(collectionSpace&&!browsing)||(browsing&&['#status','.favorites-filter'].includes(selector));if(browsing)return;if(selectedCollection!=='all')$('#view-title').textContent=collections.find(c=>c.id===selectedCollection)?.name||'Collection';if(!collectionSpace)return;$('#view-title').textContent='Your collections';$('#search').placeholder='Search collections…';$('#search').setAttribute('aria-label','Search collections');$('#list-head').hidden=true;$('#grid').className='grid collection-grid';const q=$('#search').value.toLowerCase().trim();const shown=collections.filter(c=>c.name.toLowerCase().includes(q));$('#grid').innerHTML=shown.map((c,i)=>{const image=safeArt(c.coverUrl||c.coverImage);const members=items.filter(x=>c.members.includes(x.id));return `<article class="library-item collection-tile"><button class="card" data-collection="${esc(c.id)}" aria-label="Open collection ${esc(c.name)}"><div class="collection-art" style="background:${colors[i%colors.length]}">${image?`<img src="${esc(image)}" alt="">`:`<div class="collection-mosaic">${members.slice(0,4).map(x=>cover(x)).join('')}</div>`}<span class="collection-count">${members.length} titles</span></div><h3>${esc(c.name)}</h3><div class="meta">Collection</div></button><button class="item-options" data-edit-collection="${esc(c.id)}" aria-label="Edit collection ${esc(c.name)}" title="Edit collection">✎</button></article>`}).join('');$('#empty').hidden=shown.length>0}
function render(){renderLibrary();const home=view==='home';$('#library-page').hidden=home;$('#home-page').hidden=!home;$('#create-type').hidden=true;$('#library-settings').hidden=view==='catalog';$('#select-mode').hidden=view!=='all'||collectionSpace;$('#select-mode').setAttribute('aria-pressed',String(selectMode));$('#select-mode').textContent=selectMode?'✓ Done':'☑ Select';if(home){$('header>span').textContent='My space / Home';renderHome()}else if(view==='all'&&!collectionSpace){document.querySelectorAll('[data-library-id]').forEach(card=>{const x=items.find(x=>x.id===card.dataset.libraryId);const heart=document.createElement('button');heart.className='favorite-toggle';heart.dataset.heart=x.id;heart.setAttribute('aria-label',(x.favorite?'Unfavorite ':'Favorite ')+x.title);heart.setAttribute('aria-pressed',String(!!x.favorite));heart.textContent=x.favorite?'♥':'♡';card.append(heart)})}renderSelection()}
function toggleSelection(id){selection.has(id)?selection.delete(id):selection.add(id);renderSelection()}
function renderSelection(){for(const id of selection)if(!items.some(x=>x.id===id))selection.delete(id);document.querySelectorAll('[data-library-id]').forEach(card=>{card.classList.toggle('is-selected',selection.has(card.dataset.libraryId));card.querySelector('[data-id]').setAttribute('aria-pressed',String(selection.has(card.dataset.libraryId)))});const bar=$('#bulk-bar');bar.hidden=view!=='all'||collectionSpace||(!selection.size&&!selectMode);if(bar.hidden)return;bar.innerHTML=`<span><b>${selection.size}</b> selected</span><button data-bulk="all">Select visible</button><button data-bulk="clear">Clear</button><button data-bulk="favorite">♥ Favorite</button><button data-bulk="unfavorite">♡ Unfavorite</button><select id="bulk-status" aria-label="Set selected titles status"><option value="">Set status…</option>${statuses.map(s=>`<option value="${s}">${s==='Want to experience'?'Up next':s}</option>`).join('')}</select><select id="bulk-collection" aria-label="Add selected titles to collection"><option value="">Add to collection…</option>${collections.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select><button class="danger" data-bulk="remove">Remove</button>`;$('#bulk-status').onchange=e=>{if(!selection.size||!e.target.value)return;items.filter(x=>selection.has(x.id)).forEach(x=>x.status=e.target.value);persist();render();toast('Status updated')};$('#bulk-collection').onchange=e=>{const c=collections.find(c=>c.id===e.target.value);if(!c||!selection.size)return;c.members=[...new Set([...c.members,...selection])];saveCollections();toast('Added selected titles to '+c.name);renderSelection()};bar.onclick=e=>{const action=e.target.dataset.bulk;if(!action)return;if(action==='all'){document.querySelectorAll('[data-library-id]').forEach(card=>selection.add(card.dataset.libraryId));renderSelection();return}if(action==='clear'){selection.clear();renderSelection();return}if(!selection.size)return;if(action==='remove'){if(!confirm('Remove '+selection.size+' selected titles from your library?'))return;items=items.filter(x=>!selection.has(x.id));selection.clear()}else items.filter(x=>selection.has(x.id)).forEach(x=>x.favorite=action==='favorite');persist();render()}}
$('#select-mode').onclick=()=>{selectMode=!selectMode;if(!selectMode)selection.clear();render()};
function renderSettings(){const active=types.slice(1);$('#settings-types').innerHTML=active.map(t=>{const count=items.filter(x=>x.type===t).length;return `<div class="type-setting"><div><b>${esc(t)}</b><small>${count} library titles</small></div><select aria-label="Move ${esc(t)} titles to" data-replace-type="${esc(t)}"><option value="">${count?'Move titles to…':'No titles to move'}</option>${active.filter(v=>v!==t).map(v=>`<option>${esc(v)}</option>`).join('')}</select><button class="danger" data-remove-type="${esc(t)}" ${active.length===1?'disabled':''}>Remove</button></div>`}).join('');$('#default-layout').value=layout}
$('#library-settings').onclick=()=>{renderSettings();$('#settings-dialog').showModal()};
$('#default-layout').onchange=e=>setLayout(e.target.value);
$('#settings-types').onclick=e=>{const target=e.target.closest('[data-remove-type]');if(!target)return;const name=target.dataset.removeType;const replacement=target.parentElement.querySelector('select').value;const affected=items.filter(x=>x.type===name);if(affected.length&&!replacement){toast('Choose a destination type for these titles first');return}if(!confirm('Remove the '+name+' type'+(affected.length?' and move its '+affected.length+' titles to '+replacement:'')+'?'))return;affected.forEach(x=>x.type=replacement);const index=types.indexOf(name);types.splice(index,1);labels.splice(index,1);customTypes=customTypes.filter(t=>t!==name);removedTypes=[...new Set([...removedTypes,name])];localStorage.setItem('folio-types-v1',JSON.stringify(customTypes));localStorage.setItem('folio-removed-types',JSON.stringify(removedTypes));persist();type='All media';fillTypeSelect($('#add-form select[name=type]'));renderSettings();render();toast('Media type removed')};
// Recommendations are local, explainable, and ready for richer provider metadata.
// Signals: explicit favorites and personal ratings; shared genres, creators,
// media type and release era. Owned titles are excluded from discovery suggestions.
function recommendTitles(){const liked=items.filter(x=>x.favorite||Number(x.rating)>=7);const normalize=v=>String(v||'').trim().toLowerCase();return catalogItems().filter(x=>!owned(x)&&!removedTypes.includes(x.type)).map(candidate=>{let best=null;for(const source of liked){let score=0,reasons=[];const sharedGenres=genresOf(candidate).filter(t=>genresOf(source).map(normalize).includes(normalize(t)));if(sharedGenres.length){score+=sharedGenres.length*3;reasons.push(sharedGenres.join(', '))}if(candidate.creator&&normalize(candidate.creator)===normalize(source.creator)){score+=4;reasons.push('the same creator')}if(candidate.type===source.type){score+=1;reasons.push(({Music:'more music',Anime:'more anime',Movie:'another movie',Game:'another game',Book:'another book','TV show':'another TV show','Visual novel':'another visual novel'})[candidate.type]||'the same media type')}if(candidate.year&&source.year&&Math.abs(candidate.year-source.year)<=5)score+=0.5;if(score===0)continue;score*=1+(source.favorite?0.3:0)+Math.max(0,(Number(source.rating)||0)-7)*0.1;if(!best||score>best.score)best={score,source,reasons}}return {candidate,...(best||{score:0,reasons:[]})}}).sort((a,b)=>b.score-a.score||a.candidate.title.localeCompare(b.candidate.title))}
function renderHome(){const now=new Date(),past=now.getFullYear()-1;const memories=items.flatMap(x=>(x.sessions||[]).filter(session=>{const d=new Date(session.started);return d.getFullYear()===past&&d.getMonth()===now.getMonth()&&d.getDate()===now.getDate()}).map(session=>({x,session})));const completed=items.filter(x=>x.status==='Completed').length;const top=items.filter(x=>x.rating).sort((a,b)=>b.rating-a.rating)[0];$('#home-page').innerHTML=`<div class="home-heading"><h1>Welcome to Folio<span>.</span></h1></div><div class="home-columns"><section class="home-panel home-feature"><div class="section-heading"><h2>You might enjoy</h2><div class="carousel-controls"><button id="recommend-prev" aria-label="Previous recommendation">‹</button><button id="recommend-pause" aria-label="Pause recommendations" title="Pause recommendations" aria-pressed="false">Ⅱ</button><button id="recommend-next" aria-label="Next recommendation">›</button></div></div><div id="recommendation"></div></section><section class="home-panel"><small>ON THIS DAY</small><h2>${now.toLocaleDateString([], {month:'long',day:'numeric'})}</h2>${memories.length?memories.map(({x})=>`<p>Last year on this day, you spent time with <button class="inline-link" data-memory="${esc(x.id)}">${esc(x.title)}</button>.</p>`).join(''):'<p>No sessions recorded on this day last year yet.</p><p class="muted">Log dated sessions on a title’s status page to build your own time capsule.</p>'}</section><section class="home-panel"><small>FROM YOUR LIBRARY</small><h2>Did you know?</h2><p>You have <strong>${items.length} titles</strong> across <strong>${new Set(items.map(x=>x.type)).size} media types</strong>, and have completed ${completed}.</p>${top?`<p>Your highest-rated title is <button class="inline-link" data-memory="${esc(top.id)}">${esc(top.title)}</button>, at ${top.rating}/10.</p>`:''}</section><section class="home-panel"><small>KEEP EXPLORING</small><h2>Your collections</h2>${collections.map(c=>`<button class="home-collection" data-home-collection="${esc(c.id)}">${esc(c.name)} <span>${items.filter(x=>c.members.includes(x.id)).length} titles ↗</span></button>`).join('')||'<p>Create a collection to bring related titles together.</p>'}</section></div>`;renderRecommendation();$('#recommend-prev').onclick=()=>{recommendationIndex--;renderRecommendation()};$('#recommend-next').onclick=()=>{recommendationIndex++;renderRecommendation()};$('#recommend-pause').onclick=e=>{const paused=e.target.getAttribute('aria-pressed')!=='true';e.target.setAttribute('aria-pressed',String(paused));e.target.textContent=paused?'▷':'Ⅱ';e.target.setAttribute('aria-label',paused?'Resume recommendations':'Pause recommendations');e.target.title=paused?'Resume recommendations':'Pause recommendations'};$('#home-page').onclick=e=>{const memory=e.target.closest('[data-memory]');if(memory)openDetail(memory.dataset.memory);const collection=e.target.closest('[data-home-collection]');if(collection){view='all';collectionSpace=false;selectedCollection=collection.dataset.homeCollection;history.pushState(null,'','#library');render()}}}
function renderRecommendation(){const recommendations=recommendTitles(),container=$('#recommendation');if(!recommendations.length){container.innerHTML='<p>Your library includes every current catalog suggestion. More recommendations will appear as the catalog grows.</p>';return}recommendationIndex=(recommendationIndex+recommendations.length)%recommendations.length;const r=recommendations[recommendationIndex],x=r.candidate;container.innerHTML=`<div class="recommend-layout"><button class="card" id="recommend-open" aria-label="Preview ${esc(x.title)}">${cover(x)}</button><div><small>${esc(x.type)} · ${x.year||''}</small><h2>${esc(x.title)}</h2><p>${r.source?`Because you liked <strong>${esc(r.source.title)}</strong> — ${esc(r.reasons.join('; '))}.`:'A discovery from the sample catalog. Favorite or rate more titles to personalize this space.'}</p><p class="muted">${esc(x.description||'Explore this title in the catalog.')}</p><button class="secondary" id="recommend-add">＋ Add to library</button><p class="disclaimer">${recommendationIndex+1} / ${recommendations.length} · Based on your library and sample metadata</p></div></div>`;$('#recommend-open').onclick=()=>openDetail(x.id);$('#recommend-add').onclick=()=>{addCatalog(x.id);renderHome()}}
setInterval(()=>{if(userPreferences.autoplay&&view==='home'&&!document.querySelector('dialog[open]')&&!document.hidden&&$('#recommend-pause')?.getAttribute('aria-pressed')==='false'&&!$('#recommendation')?.matches(':hover')&&!$('#home-page').contains(document.activeElement)){recommendationIndex++;renderRecommendation()}},10000);
for(const dialog of document.querySelectorAll('dialog')){if(dialog.id==='detail')continue;let pressedOutside=false;const outside=e=>{const r=dialog.getBoundingClientRect();return e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom};dialog.addEventListener('pointerdown',e=>pressedOutside=e.target===dialog&&outside(e));dialog.addEventListener('click',e=>{if(pressedOutside&&e.target===dialog&&outside(e))dialog.close();pressedOutside=false})}

