$('#select-mode').title='Select titles, or Ctrl-click / Command-click cards at any time';

let pendingCatalogId=null;
function openCatalogAdd(id){const x=catalogItems().find(x=>x.id===id);if(!x)return;if(owned(x)){openOwnedDetail(owned(x).id);return}pendingCatalogId=id;$('#catalog-add-heading').textContent='Add '+x.title;$('#catalog-add-collections').innerHTML=collections.map(c=>`<label class="collection-member"><input type="checkbox" value="${esc(c.id)}"><span>${esc(c.name)}</span></label>`).join('')||'<p class="muted">No collections yet. You can create them in Library → Collections.</p>';$('#catalog-add-dialog').showModal()}
function finishCatalogAdd(edit){const id=pendingCatalogId,x=catalogItems().find(x=>x.id===id);if(!x)return;const selected=[...document.querySelectorAll('#catalog-add-collections input:checked')].map(el=>el.value);const scroll=window.scrollY;addCatalog(id);const entry=owned(x);if(!entry)return;collections.forEach(c=>{if(selected.includes(c.id))c.members=[...new Set([...c.members,entry.id])]});if(selected.length)saveCollections();$('#catalog-add-dialog').close();window.scrollTo({top:scroll,behavior:'instant'});if(edit)openMediaEditor(entry.id);else if($('#detail').open)openOwnedDetail(entry.id)}
$('#catalog-add-default').onclick=()=>finishCatalogAdd(false);$('#catalog-add-edit').onclick=()=>finishCatalogAdd(true);
$('#user-settings').onclick=()=>{$('#theme-choice').value=userPreferences.theme;$('#motion-choice').value=userPreferences.motion||'system';$('#autoplay-choice').checked=userPreferences.autoplay;$('#preferences-dialog').showModal()};
